// JavaScript Number equality and ToInt32 expectations are generated by
// scripts/mouse-live-oracle.mjs, not by duplicating the Rust conversion.
use xterm_core::mouse_state::MouseButton;

#[test]
fn numeric_buttons_keep_strict_values_until_bit_encoding() {
    let fixture = include_str!("fixtures/mouse-button-numeric.tsv");
    assert_eq!(fixture.lines().count(), 26);
    for line in fixture.lines() {
        let fields: Vec<_> = line.split('\t').collect();
        assert_eq!(fields.len(), 6);
        let input: f64 = fields[0].parse().unwrap();
        let button = MouseButton::RawNumber(input);
        assert_eq!(
            button.raw_value(),
            fields[1].parse::<i32>().unwrap(),
            "{line}"
        );
        let same_number = MouseButton::RawNumber(input);
        assert_eq!(button == same_number, fields[2] == "1", "{line}");
        assert_eq!(
            button.numeric_value() == 0.0 && button.numeric_value().is_sign_negative(),
            fields[3] == "1",
            "{line}"
        );
        assert_eq!(button == MouseButton::None, fields[4] == "1", "{line}");
        assert_eq!(button == MouseButton::Wheel, fields[5] == "1", "{line}");
        if input.is_nan() {
            assert!(button.numeric_value().is_nan());
        } else {
            assert_eq!(button.numeric_value().to_bits(), input.to_bits());
        }
    }
    assert_ne!(MouseButton::RawNumber(0.5), MouseButton::RawNumber(0.6));
    assert_eq!(MouseButton::RawNumber(-0.0), MouseButton::Left);
    assert_eq!(MouseButton::Raw(-1).raw_value(), -1);
}
